namespace sv_fc0708fb44da4ebeb2eed1bfb6de50df.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per circuit, so each user gets independent state.
/// Persists across enhanced navigations within the same circuit.
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@* 
    Interactive Server component that lives in the layout.
    Because it has @rendermode InteractiveServer, it participates in
    the circuit and can subscribe to ThemeService change events.
    It cascades the ThemeService to all descendants so any child
    (static or interactive) can read/write theme state.
*@
@implements IDisposable
@inject ThemeService ThemeService

<CascadingValue Value="ThemeService" IsFixed="false">
    @ChildContent
</CascadingValue>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@* Displays current theme in the header — re-renders when ThemeService fires OnChange *@
@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;">
    @GetIcon() @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChanged;
    }

    private void HandleChanged() => InvokeAsync(StateHasChanged);

    private string GetIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" @bind="SelectedTheme">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           @bind="SelectedAccentColor" />
</div>

<button class="btn btn-primary" @onclick="Save">Save Preferences</button>

@if (_saved)
{
    <div class="alert alert-success mt-2">Preferences saved!</div>
}

@code {
    private ThemeMode SelectedTheme;
    private string SelectedAccentColor = "#0d6efd";
    private bool _saved;

    protected override void OnInitialized()
    {
        SelectedTheme = ThemeService.Theme;
        SelectedAccentColor = ThemeService.AccentColor;
    }

    private void Save()
    {
        ThemeService.Theme = SelectedTheme;
        ThemeService.AccentColor = SelectedAccentColor;
        _saved = true;
    }
}

